"""evaluate.protocol: seed bounds, game endings, rewards over teams and agents, tank frames."""

from collections.abc import Mapping
from pathlib import Path

import numpy as np
import pytest

from rllab.core import SOLO, ActionSpace, StepResult, TeamSpec, Transition
from rllab.evaluate import EvalSpec, eval_seeds, evaluate

PREY = "prey"
SPEC = TeamSpec(n_agents=2, obs_shape=(1,), actions=ActionSpace("discrete", n=2))


class TwoTeamTank:
    """A tank game of `length` steps: each step every agent earns 0.5, `SOLO` scores the step
    count and `PREY` minus it; it ends by truncation."""

    teams = {SOLO: SPEC, PREY: SPEC}
    board = "tank"

    def __init__(self, length: int) -> None:
        self.length = length
        self.t = 0
        self.seeds: list[int] = []

    def _obs(self) -> dict[str, np.ndarray]:
        return {team: np.full((2, 1), self.t, dtype=np.float32) for team in self.teams}

    def _info(self) -> dict[str, float]:
        return {"steps": self.t, "score": self.t, f"score:{SOLO}": self.t, f"score:{PREY}": -self.t}

    def reset(self, seed: int) -> tuple[dict[str, np.ndarray], dict[str, float]]:
        self.seeds.append(seed)
        self.t = 0
        return self._obs(), self._info()

    def step(self, actions: Mapping[str, np.ndarray]) -> StepResult:
        assert set(actions) == set(self.teams)
        self.t += 1
        over = self.t == self.length
        return StepResult(
            obs=self._obs(),
            reward={team: np.full(2, 0.5, dtype=np.float32) for team in self.teams},
            done={team: np.full(2, over) for team in self.teams},
            terminated=False,
            truncated=over,
            info=self._info(),
        )

    def frame(self) -> np.ndarray:
        return np.array([[0.0, 0.0, 1.0, 0.0], [self.t, 0.0, 0.1, 3.0]], dtype=np.float32)


class Still:
    """Always action 0 for both agents; counts its greedy and exploring calls."""

    def __init__(self) -> None:
        self.explored = 0
        self.greedy = 0

    def act(self, obs: np.ndarray, *, explore: bool) -> np.ndarray:
        if explore:
            self.explored += 1
        else:
            self.greedy += 1
        return np.zeros(len(obs), dtype=np.int64)

    def learn(self, t: Transition) -> None:
        raise AssertionError("evaluate must not learn")

    def save(self, path: Path) -> None:
        raise AssertionError("evaluate must not save")

    def load(self, path: Path) -> None:
        raise AssertionError("evaluate must not load")


@pytest.mark.parametrize(("train_seed", "n"), [(0, -1), (-1, 3), (999_999, 1001)])
def test_eval_seeds_refuses_out_of_range_arguments(train_seed, n):
    with pytest.raises(ValueError):
        eval_seeds(train_seed, n)


def test_eval_seeds_for_the_largest_train_seed():
    assert eval_seeds(999_999, 2) == [1_000_999_000, 1_000_999_001]


def test_eval_seeds_of_zero_games_is_empty():
    assert eval_seeds(3, 0) == []


def test_evaluate_ends_a_truncated_game_and_scores_the_spec_team():
    env = TwoTeamTank(length=4)
    agents = {SOLO: Still(), PREY: Still()}
    result = evaluate(lambda: env, agents, EvalSpec("p", train_seed=1, team=PREY, n_games=3))
    np.testing.assert_array_equal(result.scores, [-4.0, -4.0, -4.0])
    assert result.scores.dtype == np.float64
    assert env.seeds == [1_001_000, 1_001_001, 1_001_002]
    for agent in agents.values():
        assert agent.greedy == 3 * 4
        assert agent.explored == 0


def test_evaluate_records_rewards_over_every_agent_and_team_and_tank_frames():
    env = TwoTeamTank(length=3)
    agents = {SOLO: Still(), PREY: Still()}
    result = evaluate(lambda: env, agents, EvalSpec("p", train_seed=0, n_games=2, record=1))
    (game,) = result.games
    assert game.seed == 1_000_000
    assert game.board == "tank"
    assert game.frames.dtype == np.float32
    assert game.frames.shape == (4, 2, 4)
    np.testing.assert_array_equal(game.frames[:, 1, 0], [0.0, 1.0, 2.0, 3.0])
    np.testing.assert_array_equal(game.rewards, [2.0, 2.0, 2.0])
    assert game.rewards.dtype == np.float32
    np.testing.assert_array_equal(game.scores[SOLO], [0.0, 1.0, 2.0, 3.0])
    np.testing.assert_array_equal(game.scores[PREY], [0.0, -1.0, -2.0, -3.0])
    assert game.scores[PREY].dtype == np.float32


def test_evaluate_builds_one_env_for_all_games():
    made: list[TwoTeamTank] = []

    def make_env() -> TwoTeamTank:
        made.append(TwoTeamTank(length=2))
        return made[-1]

    evaluate(make_env, {SOLO: Still(), PREY: Still()}, EvalSpec("p", train_seed=0, n_games=5))
    assert len(made) == 1
    assert len(made[0].seeds) == 5

